    'normal-02',
    'normal-03',
    'normal-04',
    'connected-majority',
    'fragmented-islands',
  ].map((id) => {
    const row = sources.find((source) => source.row === `milestone-2-atlas-v2-${id}`);
    return { id, seed: row.seed, controls: row.controls };
