    total += grid.weights[y] * grid.width;
    for (let x = 0; x < grid.width; x++) {
      const i = y * grid.width + x;
      if (grid.owners[i] >= 0 && grid.values[i] > threshold) land += grid.weights[y];
    }
  }
  return land / total;
}
