  return {
    interior: coast.filter((_, i) => !removed.has(i)),
    interiorWitness: [...interiorWitness],
    attachments,
    bay: pocket,
    islandAnchorEdges: islandAnchors.map((i) =>
      ccw ? [coast[i], coast[(i + 1) % n]] : [coast[(i + 1) % n], coast[i]],
    ),
  };
}

